package com.zorykai.fishing.session;
import com.zorykai.fishing.*;
import net.minecraft.server.network.ServerPlayerEntity;
import net.minecraft.nbt.*;
import net.minecraft.item.*;
import net.minecraft.registry.Registries;
import net.minecraft.util.Identifier;
import java.util.*;
import java.io.*;
/** Compare-before/after receipt: uncertain inventory is retained for manual inspection. */
public final class ItemDelivery {
 final FishingMod mod;
 public ItemDelivery(FishingMod mod)throws Exception{this.mod=mod;mod.store.transaction(c->{try(var s=c.createStatement()){s.execute("CREATE TABLE IF NOT EXISTS item_reserves(id TEXT PRIMARY KEY,owner TEXT NOT NULL,payload BLOB NOT NULL,state TEXT NOT NULL DEFAULT 'AVAILABLE')");s.execute("CREATE TABLE IF NOT EXISTS item_deliveries(owner TEXT PRIMARY KEY,id TEXT NOT NULL,before_state BLOB NOT NULL,after_state BLOB NOT NULL,sources TEXT NOT NULL,state TEXT NOT NULL)");}return null;});}
 static byte[] encode(NbtCompound data)throws IOException{var bytes=new ByteArrayOutputStream();NbtIo.writeCompressed(data,bytes);return bytes.toByteArray();}
 static NbtCompound decode(byte[] b)throws IOException{return NbtIo.readCompressed(new ByteArrayInputStream(b),NbtSizeTracker.ofUnlimitedBytes());}
 public void quarantine(ServerPlayerEntity p,FishingSessions.Session session)throws Exception{var list=new NbtList();for(int i=0;i<p.getInventory().size();i++){var item=p.getInventory().getStack(i);if(!item.isEmpty()&&mod.engine.gearType(p,item).isEmpty())list.add(item.encode(mod.server.getRegistryManager()));}var cursor=p.currentScreenHandler.getCursorStack();if(!cursor.isEmpty()&&mod.engine.gearType(p,cursor).isEmpty())list.add(cursor.encode(mod.server.getRegistryManager()));if(list.isEmpty())return;var n=new NbtCompound();n.put("Items",list);var bytes=encode(n);mod.store.transaction(c->{try(var q=c.prepareStatement("INSERT OR IGNORE INTO item_reserves(id,owner,payload) VALUES(?,?,?)")){q.setString(1,session.id());q.setString(2,p.getUuidAsString());q.setBytes(3,bytes);q.executeUpdate();}return null;});mod.audit(p.getUuid(),"ITEM_QUARANTINE",Map.of("session",session.id(),"stacks",list.size()));}
 public void quarantineLoaded(ServerPlayerEntity p,FishingSessions.Session session,NbtCompound loaded)throws Exception{var inventory=loaded.getList("Inventory",10);boolean temporary=false;var list=new NbtList();for(int i=0;i<inventory.size();i++){var item=ItemStack.fromNbt(mod.server.getRegistryManager(),inventory.getCompound(i)).orElse(ItemStack.EMPTY);if(!mod.engine.gearType(p,item).isEmpty())temporary=true;else if(!item.isEmpty())list.add(item.encode(mod.server.getRegistryManager()));}if(!temporary||list.isEmpty())return;var n=new NbtCompound();n.put("Items",list);var bytes=encode(n);mod.store.transaction(c->{try(var q=c.prepareStatement("INSERT OR IGNORE INTO item_reserves(id,owner,payload) VALUES(?,?,?)")){q.setString(1,session.id());q.setString(2,p.getUuidAsString());q.setBytes(3,bytes);q.executeUpdate();}return null;});}
 public List<String> reserves(UUID owner)throws Exception{return mod.store.transaction(c->{var out=new ArrayList<String>();try(var q=c.prepareStatement("SELECT id FROM item_reserves WHERE owner=? AND state='AVAILABLE'")){q.setString(1,owner.toString());try(var r=q.executeQuery()){while(r.next())out.add(r.getString(1));}}return out;});}
 public boolean pending(UUID owner)throws Exception{return mod.store.transaction(c->{try(var q=c.prepareStatement("SELECT 1 FROM item_deliveries WHERE owner=? AND state!='DONE'")){q.setString(1,owner.toString());try(var r=q.executeQuery()){return r.next();}}});}
 public void claim(ServerPlayerEntity p,String source)throws Exception{
  if(mod.sessions.protectedPlayer(p))throw new IllegalStateException("Saia da pesca antes de retirar itens");if(!p.currentScreenHandler.getCursorStack().isEmpty())throw new IllegalStateException("Guarde o item do cursor");if(pending(p.getUuid())){recover(p);return;}p.closeHandledScreen();var before=p.writeNbt(new NbtCompound());var items=new ArrayList<ItemStack>();String key=source;
  if(source.startsWith("treasure:")){long count=mod.data.profile(p.getUuid()).counters.getOrDefault(source,0L);if(count<=0)throw new IllegalArgumentException("Sem itens nessa reserva");var item=Registries.ITEM.get(Identifier.of(source.substring(9)));if(item==Items.AIR||count>4096)throw new IllegalArgumentException("Item/quantidade inválida");while(count>0){int amount=(int)Math.min(item.getMaxCount(),count);items.add(new ItemStack(item,amount));count-=amount;}}
  else items=mod.store.transaction(c->{try(var q=c.prepareStatement("SELECT payload FROM item_reserves WHERE owner=? AND id=? AND state='AVAILABLE'")){q.setString(1,p.getUuidAsString());q.setString(2,source);try(var r=q.executeQuery()){if(!r.next())throw new IllegalArgumentException("Reserva indisponível");var list=decode(r.getBytes(1)).getList("Items",10);var out=new ArrayList<ItemStack>();for(int i=0;i<list.size();i++)out.add(ItemStack.fromNbt(mod.server.getRegistryManager(),list.getCompound(i)).orElseThrow());return out;}}});
  var test=new net.minecraft.entity.player.PlayerInventory(p);test.readNbt(before.getList("Inventory",10));for(var item:items)if(!test.insertStack(item.copy()))throw new IllegalStateException("Libere espaço para todos os itens");var after=before.copy();after.put("Inventory",test.writeNbt(new NbtList()));var b=encode(before);var a=encode(after);String id=UUID.randomUUID().toString();
  mod.store.transaction(c->{try(var q=c.prepareStatement("INSERT INTO item_deliveries VALUES(?,?,?,?,?,'PENDING') ON CONFLICT(owner) DO UPDATE SET id=excluded.id,before_state=excluded.before_state,after_state=excluded.after_state,sources=excluded.sources,state='PENDING' WHERE item_deliveries.state='DONE'")){q.setString(1,p.getUuidAsString());q.setString(2,id);q.setBytes(3,b);q.setBytes(4,a);q.setString(5,key);if(q.executeUpdate()!=1)throw new IllegalStateException("Entrega já reservada");}return null;});recover(p);
 }
 public void recover(ServerPlayerEntity p)throws Exception{if(mod.sessions.protectedPlayer(p))return;mod.store.transaction(c->{try(var q=c.prepareStatement("SELECT id,before_state,after_state,sources FROM item_deliveries WHERE owner=? AND state!='DONE'")){q.setString(1,p.getUuidAsString());try(var r=q.executeQuery()){if(!r.next())return null;String id=r.getString(1),source=r.getString(4);var before=decode(r.getBytes(2));var after=decode(r.getBytes(3));var current=p.getInventory().writeNbt(new NbtList());boolean wasBefore=mod.sessions.sameInventory(before.getList("Inventory",10),current),wasAfter=mod.sessions.sameInventory(after.getList("Inventory",10),current);if(!wasBefore&&!wasAfter)throw new IOException("Inventário alterado durante entrega; reserva preservada para conferência "+id);if(wasBefore)p.getInventory().readNbt(after.getList("Inventory",10));mod.sessions.saveVerified(p,after);if(source.startsWith("treasure:")){var d=mod.data.profile(c,p.getUuid());d.counters.remove(source);mod.data.save(c,p.getUuid(),d);}else try(var update=c.prepareStatement("UPDATE item_reserves SET state='DONE' WHERE id=? AND owner=?")){update.setString(1,source);update.setString(2,p.getUuidAsString());update.executeUpdate();}try(var update=c.prepareStatement("UPDATE item_deliveries SET state='DONE' WHERE owner=? AND id=?")){update.setString(1,p.getUuidAsString());update.setString(2,id);update.executeUpdate();}mod.data.audit(c,p.getUuid(),"ITEM_DELIVERY",Map.of("id",id,"source",source));}}return null;});p.getInventory().markDirty();p.playerScreenHandler.sendContentUpdates();}
}
